class Throughput(object):
    def __init__(self, client_data_collection, throughput_filter, throughput_calculators, recorder):
        self._client_data_collection = client_data_collection
        self._filter = throughput_filter
        self._throughput_calculators = throughput_calculators
        self._recorder = recorder

    def analyze(self):
        self.reset()
        self._recorder.start()
        for data in self._filter.do():
            if data is None:
                continue
            self._update(data)
        self._finalize()

    def _update(self, data):

        data = self._client_data_collection.update(data)
        if data:
            self._recorder.add(data)
            for calculator in self._throughput_calculators:
                calculator.calculate(self._client_data_collection)

    def _finalize(self):
        self._client_data_collection.finalize()
        self._recorder.stop()

    def get_result(self):
        return self._client_data_collection.result

    def on_analyze(self, log_entry):
        data = self._filter.on_filter(log_entry)
        if data is not None:
            self._update(data)

    def reset(self):
        self._client_data_collection.reset()
        self._recorder.reset()

    @property
    def recorder(self):
        return self._recorder
